import heapq
from typing import List, Mapping, Optional, Tuple, Set, Dict


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits:
        raise KeyError(src)
    if dst not in limits:
        raise KeyError(dst)
    if src == dst:
        raise ValueError("src and dst must be different")

    best: Dict[str, Tuple[int, int]] = {}
    parent: Dict[str, str] = {}
    pq: List[Tuple[int, int, str]] = [(-float('inf'), 0, src)]
    visited: Set[str] = set()

    while pq:
        neg_bottleneck, hops, node = heapq.heappop(pq)
        bottleneck = -neg_bottleneck

        if node in visited:
            continue
        visited.add(node)

        if node == dst:
            path = [dst]
            current = dst
            while current in parent:
                current = parent[current]
                path.append(current)
            path.reverse()
            return (bottleneck, path)

        if node in limits:
            neighbors = sorted(limits[node].items())
            for neighbor, weight in neighbors:
                if neighbor in visited:
                    continue
                new_bottleneck = min(bottleneck, weight)
                new_hops = hops + 1
                if neighbor not in best or new_bottleneck > best[neighbor][0] or (new_bottleneck == best[neighbor][0] and new_hops < best[neighbor][1]):
                    best[neighbor] = (new_bottleneck, new_hops)
                    parent[neighbor] = node
                    heapq.heappush(pq, (-new_bottleneck, new_hops, neighbor))

    return None
